using System.Collections.Generic; public sealed class CargoRailPuzzleController:ValidatedPuzzleController { private readonly List<string> route=new();protected override void ResetPuzzle()=>route.Clear();public void SetRoute(IEnumerable<string> nodes){route.Clear();if(nodes!=null)route.AddRange(nodes);}public bool Submit(string start,string end)=>CompleteWhen(route.Count>=2&&route[0]==start&&route[^1]==end,string.Join(",",route)); }
